/**
 * A release App Bundle must never be built with the debug App Check provider.
 *
 * `plugins/withAppCheckEnvGuard.js` rewrites the generated `android/app/build.gradle`, and what is
 * worth testing is not that it edits text -- it is that the edit cannot silently fail, and that the
 * Groovy it injects gates the right task. `android/` is regenerated by every prebuild, so a change
 * to Expo's template is the realistic way this breaks; the plugin throws when its anchor moves and
 * these tests hold it to that.
 *
 * The task predicate is checked here too, because getting it wrong is not hypothetical: the obvious
 * `startsWith('bundle') && endsWith('Release')` also matches `bundleLibCompileToJarRelease` and
 * `bundleLibRuntimeToJarRelease`, which the Expo library modules contribute to EVERY release build.
 * That version blocked `assembleRelease` -- the emulator path -- and was caught only by running it.
 *
 * Written in JavaScript because the subject is a CommonJS config plugin; `tsconfig.json` only
 * includes `.ts`/`.tsx`, so this file is linted and run but not type-checked.
 */
const fs = require('fs');
const path = require('path');

const { patch } = require('../plugins/withAppCheckEnvGuard');

/** The part of Expo's template the plugin anchors to, verbatim. */
const TEMPLATE = `apply plugin: "com.android.application"

def jscFlavor = 'io.github.react-native-community:jsc-android:2026004.+'

android {
    namespace 'com.kruegerco.silentsum'
    defaultConfig {
        versionCode 1
        versionName "0.1.0"
    }
}
`;

describe('withAppCheckEnvGuard', () => {
  it('injects the guard above the android block', () => {
    const out = patch(TEMPLATE);
    expect(out).toContain('SILENTSUM_APP_CHECK_ENV_GUARD');
    expect(out.indexOf('SILENTSUM_APP_CHECK_ENV_GUARD')).toBeLessThan(out.indexOf('\nandroid {'));
    // The template itself must survive intact; the guard is an addition, not a rewrite.
    expect(out).toContain("namespace 'com.kruegerco.silentsum'");
    expect(out).toContain('versionCode 1');
  });

  it('gates only :app:bundleRelease, so assembleRelease still works', () => {
    const out = patch(TEMPLATE);
    expect(out).toContain("t.path == ':app:bundleRelease'");
    // The predicate that wrongly caught the Expo modules' own bundle tasks, and with them the
    // emulator's `assembleRelease`. Its absence is the regression guard -- but it is quoted in a
    // comment explaining why it is wrong, so only executable lines can be asserted on.
    const code = out
      .split('\n')
      .filter((line) => !line.trim().startsWith('//'))
      .join('\n');
    expect(code).not.toMatch(/startsWith\('bundle'\)/);
    expect(code).not.toMatch(/endsWith\('Release'\)/);
  });

  it('demands exactly prod, not merely "not dev"', () => {
    const out = patch(TEMPLATE);
    expect(out).toContain("if (silentsumBuildEnv != 'prod')");
    // An unset variable is the realistic mistake, and must be reported as such rather than as an
    // empty string in the message.
    expect(out).toContain('"(unset)"');
  });

  it('is idempotent, so a second prebuild does not stack two copies', () => {
    const once = patch(TEMPLATE);
    expect(patch(once)).toBe(once);
  });

  it('throws rather than silently producing an unguarded build.gradle', () => {
    expect(() => patch('android{\n}\n')).toThrow(/could not find the .android \{. block/);
  });

  it('matches what is actually in the generated build.gradle on this machine', () => {
    // `android/` is git-ignored, so on a fresh checkout there is nothing to compare against and
    // this check simply does not apply. Where it does exist, it is the file Gradle really reads,
    // and it drifting from the plugin is exactly the failure this pair of copies invites.
    const generated = path.join(__dirname, '..', 'android', 'app', 'build.gradle');
    if (!fs.existsSync(generated)) return;
    const contents = fs.readFileSync(generated, 'utf8');
    expect(contents).toContain('SILENTSUM_APP_CHECK_ENV_GUARD');
    expect(contents).toContain("t.path == ':app:bundleRelease'");
    expect(contents).toContain("if (silentsumBuildEnv != 'prod')");
  });
});
